import { Calls as CallsList } from './calls/Calls';
import { GroupCallLayer } from './call/GroupCall';
import { CallLayer } from './call/CallLayer';
import { JoinLink } from './group/JoinLink';
import { useChatTheme } from '../chatTheme';
import { ForwardPicker } from './ForwardPicker';
import { FolderColumn, useFolderPlace } from './folderNav';
import { addHotkeys, AsidePanel, FloatShell, ModalRoot, Presence, SideFrame, SlideStack, Toast } from '@relay/ui';
import { useEffect, useRef, useState } from 'preact/hooks';
import { getGlobal, setGlobal, useGlobal } from '../global';
import { GLOBAL_SEARCH } from '../shortcuts';
import { home, orderFor } from '../nav';
import { useWallpaper } from '../wallpapers';
import { useWallpaperImage } from '../wallpaperImage';
import { ChatStack } from './ChatStack';
import { Info } from './Info';
import { Login } from './Login';
import { NewChat } from './NewChat';
import { QrConfirm } from './QrLogin';
import { DevPlate } from './settings/DevPlate';
import { lazy } from './lazy';
import { Contacts } from './contacts/Contacts';
import { Archive } from './Archive';
import { NewGroupMembers, NewGroupName } from './newChat/NewGroup';
import { NewChannelInfo, NewChannelMembers } from './newChat/NewChannel';
import { EditContact } from './contacts/EditContact';
import { NewContact } from './contacts/NewContact';
import { Sidebar } from './Sidebar';

// страницы настроек — отдельным чанком (ui/lazy.tsx, settings/pages.ts): в основной бандл не входят, догружаются в простое
const pages = () => import('./settings/pages');
const Main = lazy(() => pages().then((m) => m.Main));
const Profile = lazy(() => pages().then((m) => m.Profile));
const Links = lazy(() => pages().then((m) => m.Links));
const LinkEdit = lazy(() => pages().then((m) => m.LinkEdit));
const General = lazy(() => pages().then((m) => m.General));
const Wallpaper = lazy(() => pages().then((m) => m.Wallpaper));
const WallpaperColor = lazy(() => pages().then((m) => m.WallpaperColor));
const Shortcuts = lazy(() => pages().then((m) => m.Shortcuts));
const Notifications = lazy(() => pages().then((m) => m.Notifications));
const Calls = lazy(() => pages().then((m) => m.Calls));
const Privacy = lazy(() => pages().then((m) => m.Privacy));
const Blocked = lazy(() => pages().then((m) => m.Blocked));
const Password = lazy(() => pages().then((m) => m.Password));
const Passkeys = lazy(() => pages().then((m) => m.Passkeys));
const PeoplePicker = lazy(() => pages().then((m) => m.PeoplePicker));
const PrivacyRule = lazy(() => pages().then((m) => m.PrivacyRule));
const Performance = lazy(() => pages().then((m) => m.Performance));
const Sessions = lazy(() => pages().then((m) => m.Sessions));
const Folders = lazy(() => pages().then((m) => m.Folders));
const FolderEdit = lazy(() => pages().then((m) => m.FolderEdit));
const FolderChats = lazy(() => pages().then((m) => m.FolderChats));
const Data = lazy(() => pages().then((m) => m.Data));
const Autoload = lazy(() => pages().then((m) => m.Autoload));
const Dev = lazy(() => pages().then((m) => m.Dev));



// ширина списка чатов, которую пользователь вытянул за край (null — по умолчанию)
const SIDE_KEY = 'relay.sideWidth';
// каркас из index.html был показан (boot.js): его обои уже на экране — свои без узора не показываем (Wallpaper waitPattern)
const SHELL_SHOWN = typeof document !== 'undefined' && document.documentElement.hasAttribute('data-shell-was');
const savedSide = (() => { try { const v = Number(localStorage.getItem(SIDE_KEY)); return v > 0 ? Math.min(480, Math.max(320, v)) : undefined; } catch { return undefined; } })();   // в пределах перетаскивания, 320…480
const saveSide = (w: number | null) => { try { if (w) localStorage.setItem(SIDE_KEY, String(w)); else localStorage.removeItem(SIDE_KEY); } catch { /* приватный режим */ } };

export function App() {
  const folderPlace = useFolderPlace();
  const boot = useGlobal((s) => s.boot);
  const openChatId = useGlobal((s) => s.openChatId);
  const view = useGlobal((s) => s.sidebarView);
  const hasStack = useGlobal((s) => s.chatStack.length > 0);
  const infoOpen = useGlobal((s) => s.infoOpen);
  const listLeaving = useGlobal((s) => s.listLeaving);
  // телефон: какой экран сверху — список, чат или «Информация» (на широком экране атрибут ни на что не влияет)
  const screen = !openChatId || listLeaving ? 'list' : infoOpen ? 'info' : 'chat';
  const { wp, dark, key: wpKey } = useWallpaper();
  // у открытого чата своя тема — за ним её обои (узор и сила — свои), своя картинка уступает
  const chatWp = useChatTheme(openChatId)?.wallpaper?.colors ?? null;
  const ownImage = useWallpaperImage(wpKey, wp.image);
  const wpImage = chatWp ? null : ownImage;
  const enter = useGlobal((s) => s.enter);
  // вошли: экран входа ещё 320 мс лежит сверху и гаснет, под ним выезжает приложение (как в Telegram Web K)
  const [leaving, setLeaving] = useState(false);
  const prevBoot = useRef(boot);
  if (prevBoot.current === 'login' && boot === 'app' && !leaving) setLeaving(true);
  prevBoot.current = boot;
  useEffect(() => { if (!leaving) return; const t = setTimeout(() => setLeaving(false), 320); return () => clearTimeout(t); }, [leaving]);
  // ⌘⇧F / Ctrl+Shift+F — поиск по всем чатам: из настроек сначала назад к списку, потом фокус в поле (оно и открывает поиск)
  useEffect(() => {
    if (boot !== 'app') return;
    return addHotkeys({
      [GLOBAL_SEARCH]: () => {
        void (async () => {
          if (getGlobal().sidebarView !== 'chats') await home();
          requestAnimationFrame(() => (document.getElementById('side-search') as HTMLInputElement | null)?.focus());
        })();
      },
    });
  }, [boot]);
  if (boot === 'loading') return null;
  // один и тот же слой входа в обоих состояниях (ключ) — карточка не пересоздаётся, пока гаснет
  const login = boot === 'login' || leaving ? <div key="login" class={'app-login-layer' + (boot === 'app' ? ' is-leaving' : '')}><Login /></div> : null;
  if (boot === 'login') return <>{login}<AppToast key="toast" /></>;   // тост «Сеанс завершён…» переживает уход на вход
  return (
    <>
      <FloatShell key="shell" screen={screen} class={(openChatId ? 'app-chat-open' : '') + (enter ? ' app-enter-' + enter : '')} rail={folderPlace === 'left' ? <FolderColumn /> : null} pattern={wp.pattern} wallpaperColors={chatWp ?? wp.colors} wallpaperBlur={wp.blur} wallpaperDark={dark} wallpaperIntensity={wp.intensity} wallpaperImage={wpImage} wallpaperWaitPattern={SHELL_SHOWN} sideWidth={savedSide} onSideResize={saveSide} aside={<AsidePanel open={infoOpen && !!openChatId} onClose={() => setGlobal({ infoOpen: false })} label="Информация"><Info /></AsidePanel>} sidebar={<SideFrame><SlideStack order={orderFor(view)} active={view} render={(k: string) => (k === 'chats' ? <Sidebar /> : k === 'settings' ? <Main /> : k === 'settings/profile' ? <Profile /> : k === 'settings/profile/links' ? <Links /> : /^settings\/profile\/links\/(new|\d+)$/.test(k) ? <LinkEdit key={k} path={k} /> : k === 'settings/general' ? <General /> : k === 'settings/general/wallpaper' ? <Wallpaper /> : k === 'settings/general/wallpaper/color' ? <WallpaperColor /> : k === 'settings/general/shortcuts' ? <Shortcuts /> : k === 'settings/notifications' ? <Notifications /> : k === 'settings/calls' ? <Calls /> : k === 'settings/privacy' ? <Privacy /> : k === 'settings/privacy/blocked' ? <Blocked /> : k === 'settings/privacy/password' ? <Password /> : k === 'settings/privacy/passkeys' ? <Passkeys /> : /^settings\/privacy\/rule\/[^/]+\/(allow|deny)$/.test(k) ? <PeoplePicker key={k} path={k} /> : /^settings\/privacy\/rule\/[^/]+$/.test(k) ? <PrivacyRule key={k} path={k} /> : k === 'archive' ? <Archive /> : k === 'contacts' ? <Contacts /> : k === 'calls' ? <CallsList /> : k === 'newGroup' ? <NewGroupMembers /> : k === 'newGroup/name' ? <NewGroupName /> : k === 'newChannel' ? <NewChannelInfo /> : k === 'newChannel/members' ? <NewChannelMembers /> : /^contacts\/\d+\/edit$/.test(k) ? <EditContact key={k} path={k} active={k === view} /> : k === 'settings/performance' ? <Performance /> : k === 'settings/sessions' ? <Sessions /> : k === 'settings/folders' ? <Folders /> : /^settings\/folders\/(new|\d+)$/.test(k) ? <FolderEdit key={k} path={k} /> : /^settings\/folders\/(new|\d+)\/(include|exclude)$/.test(k) ? <FolderChats key={k} path={k} /> : k === 'settings/data' ? <Data /> : /^settings\/data\/autoload\/(photo|video|file)$/.test(k) ? <Autoload path={k} /> : k === 'settings/dev' ? <Dev /> : null)} /></SideFrame>}>
        {hasStack ? <ChatStack /> : null /* чат не выбран — как в Telegram Web, посередине только обои */}
      </FloatShell>
      <NewChat />
      <ModalRoot />
      <CallLayer />
      <GroupCallLayer />
      <ForwardPicker />
      <JoinLink />
      <NewContact />
      <DevPlate />
      <AppToast />
      <QrConfirm />
      {login}
    </>
  );
}

/** Общий тост (ошибки сохранения настроек): живёт над всем приложением, уходит плавно. */
function AppToast() {
  const toast = useGlobal((s) => s.toast);
  const last = useRef('');
  if (toast) last.current = toast.text;
  return (
    <Presence show={!!toast} exitMs={200}>
      <div class="app-toast app-toast-global"><Toast>{toast?.text ?? last.current}</Toast></div>
    </Presence>
  );
}
