import { SAVED_TITLE } from '@relay/protocol';
import { peerTone } from '@relay/ui';
import { getPrefs, localeTimeFormat } from '../prefs';

export { localeTimeFormat };

const pad = (n: number) => String(n).padStart(2, '0');

export type TimeFormat = '12h' | '24h';

/** Часы:минуты в нужном формате; fmt не задан — настройка устройства (null → локаль). */
export function hm(d: Date, fmt: TimeFormat = getPrefs().timeFormat ?? localeTimeFormat()): string {
  if (fmt === '24h') return `${pad(d.getHours())}:${pad(d.getMinutes())}`;
  const h = d.getHours();
  return `${h % 12 || 12}:${pad(d.getMinutes())} ${h < 12 ? 'AM' : 'PM'}`;
}

/**
 * Время в строке чата — как в Telegram: сегодня — часы, в этом году на этой неделе — день недели («пн»),
 * раньше в этом году — «12 мар», другой год — полная дата «12.03.2025». «Вчера» нет: вчера — тоже день недели.
 */
export function chatTime(iso: string | undefined, fmt?: TimeFormat, now = new Date()): string {
  if (!iso) return '';
  const d = new Date(iso);
  if (d.getTime() <= 0) return '';
  const day = (x: Date) => new Date(x.getFullYear(), x.getMonth(), x.getDate()).getTime();
  const diff = Math.round((day(now) - day(d)) / 86_400_000);
  if (diff === 0) return hm(d, fmt);
  if (d.getFullYear() !== now.getFullYear()) return `${pad(d.getDate())}.${pad(d.getMonth() + 1)}.${d.getFullYear()}`;
  // неделя с понедельника: «вс» прошлой недели в понедельник — уже дата
  const sinceMonday = (now.getDay() + 6) % 7;
  if (diff > 0 && diff <= sinceMonday) return d.toLocaleDateString('ru-RU', { weekday: 'short' });
  return `${d.getDate()} ${MONTHS_SHORT[d.getMonth()]}`;
}

// свои сокращения: у ICU для части месяцев нет короткой формы («3 марта», «мая»)
const MONTHS_SHORT = ['янв', 'фев', 'мар', 'апр', 'мая', 'июн', 'июл', 'авг', 'сен', 'окт', 'ноя', 'дек'];

export function clock(iso: string, fmt?: TimeFormat): string {
  return hm(new Date(iso), fmt);
}

// Форматтеры Intl создаются один раз: toLocaleDateString с параметрами строил новый на каждое сообщение ленты
const DAY_SAME_YEAR = new Intl.DateTimeFormat('ru-RU', { day: 'numeric', month: 'long' });
const DAY_OTHER_YEAR = new Intl.DateTimeFormat('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' });
const dayLabels = new Map<string, string>();   // день + сегодняшний день («Сегодня/Вчера» зависят от него) → подпись

export function dayLabel(iso: string): string {
  const d = new Date(iso), now = new Date();
  const day = (x: Date) => new Date(x.getFullYear(), x.getMonth(), x.getDate()).getTime();
  const key = day(d) + ':' + day(now);
  const hit = dayLabels.get(key);
  if (hit) return hit;
  const diff = Math.round((day(now) - day(d)) / 86_400_000);
  const label = diff === 0 ? 'Сегодня' : diff === 1 ? 'Вчера'
    : (d.getFullYear() === now.getFullYear() ? DAY_SAME_YEAR : DAY_OTHER_YEAR).format(d);
  if (dayLabels.size > 500) dayLabels.clear();
  dayLabels.set(key, label);
  return label;
}

export function dayKey(iso: string): string {
  const d = new Date(iso);
  return `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
}

/** Подзаголовок личного чата, как в Telegram: «в сети», «был(а) 5 мин. назад», «был(а) вчера в 21:05»… */
export function lastSeenText(online: boolean, lastSeen: string | null, now = Date.now()): string {
  if (online) return 'в сети';
  if (lastSeen === 'recently') return 'был(а) недавно';   // время скрыто правилом «Последний визит»
  if (!lastSeen) return 'был(а) давно';
  const d = new Date(lastSeen), ago = now - d.getTime();
  if (ago < 60_000) return 'был(а) только что';
  if (ago < 3_600_000) return `был(а) ${Math.floor(ago / 60_000)} мин. назад`;
  const day = (x: Date) => new Date(x.getFullYear(), x.getMonth(), x.getDate()).getTime();
  const days = Math.round((day(new Date(now)) - day(d)) / 86_400_000);
  const at = hm(d);
  if (days === 0) return `был(а) в ${at}`;
  if (days === 1) return `был(а) вчера в ${at}`;
  if (days < 7) return `был(а) ${d.toLocaleDateString('ru-RU', { day: 'numeric', month: 'short' })} в ${at}`;
  return `был(а) ${pad(d.getDate())}.${pad(d.getMonth() + 1)}.${String(d.getFullYear()).slice(2)}`;
}

/** Размер файла: 812 Б, 34 КБ, 2,4 МБ. */
export function fileSize(n: number): string {
  if (n < 1024) return n + ' Б';
  if (n < 1024 * 1024) return Math.round(n / 1024) + ' КБ';
  return (n / 1024 / 1024).toFixed(1).replace('.', ',') + ' МБ';
}

/** День рождения: год необязателен. */
export interface Birthday { day: number; month: number; year?: number }

export const MONTHS_GEN = ['января', 'февраля', 'марта', 'апреля', 'мая', 'июня', 'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря'];

/** Полных лет на дату now (по местному календарю). */
export function age(b: Birthday, now = new Date()): number | null {
  if (!b.year) return null;
  let n = now.getFullYear() - b.year;
  if (now.getMonth() + 1 < b.month || (now.getMonth() + 1 === b.month && now.getDate() < b.day)) n--;
  return n >= 0 ? n : null;
}

const yearsWord = (n: number) => {
  const d = n % 10, h = n % 100;
  return d === 1 && h !== 11 ? 'год' : d >= 2 && d <= 4 && (h < 12 || h > 14) ? 'года' : 'лет';
};

/** «29 апреля (34 года)»; без года — «29 апреля». */
export function birthdayText(b: Birthday, now = new Date()): string {
  const base = `${b.day} ${MONTHS_GEN[b.month - 1] ?? ''}`.trim();
  const a = age(b, now);
  return a == null ? base : `${base} (${a} ${yearsWord(a)})`;
}

const dayStart = (x: Date) => new Date(x.getFullYear(), x.getMonth(), x.getDate()).getTime();

/** Последняя активность сеанса в списке: «сегодня в 14:05», «вчера», «12.10.26». */
export function sessionTime(iso: string, now = new Date(), fmt?: TimeFormat): string {
  const d = new Date(iso);
  const days = Math.round((dayStart(now) - dayStart(d)) / 86_400_000);
  if (days <= 0) return `сегодня в ${hm(d, fmt)}`;
  if (days === 1) return 'вчера';
  return `${pad(d.getDate())}.${pad(d.getMonth() + 1)}.${String(d.getFullYear()).slice(2)}`;
}

/** Полная дата для деталей сеанса: «17 октября 2026 в 14:05». */
export function fullDateTime(iso: string, fmt?: TimeFormat): string {
  const d = new Date(iso);
  return `${d.getDate()} ${MONTHS_GEN[d.getMonth()]} ${d.getFullYear()} в ${hm(d, fmt)}`;
}

/** Фрагмент вокруг совпадения: длинное начало обрезаем, чтобы найденное было видно в строке. */
export function snippet(text: string, q: string): string {
  const i = text.toLowerCase().indexOf(q.toLowerCase());
  if (i <= 24) return text;
  const from = text.lastIndexOf(' ', i - 12);
  return '…' + text.slice(from > 0 ? from + 1 : i - 12);
}

/** Цвет чата: у личного — собеседника, у группы — по id чата. */
export function chatTone(chat: Record<string, unknown> | null | undefined): number | undefined {
  const id = (chat?.peerId as number | null | undefined) ?? (chat?.id as number | undefined);
  return id == null ? undefined : peerTone(id);
}

/** Личный чат с системным пользователем «Relay». */
export const isSystemChat = (chat: Record<string, unknown> | null | undefined): boolean => !!(chat?.peer as { system?: boolean } | null)?.system;

/** «Избранное» — чат с самим собой. */
export const isSavedChat = (chat: Record<string, unknown> | null | undefined): boolean => !!chat?.saved;
/** Галочки своего сообщения: в «Избранном» читать некому — только «отправляется» и «не отправлено» (как в Telegram). */
export const shownStatus = (status: unknown, saved: boolean): string | undefined =>
  saved && status !== 'pending' && status !== 'failed' ? 'none' : status as string | undefined;
/** Запрос подходит к «Избранному» (поиск находит его, даже если чата ещё нет). */
export const matchesSaved = (q: string): boolean => { const n = q.trim().toLowerCase(); return !!n && SAVED_TITLE.toLowerCase().startsWith(n); };

/** Код входа в превью и уведомлениях: цифры кода — точками. */
export const hideCode = (text: string): string => text.replace(/\d{5}/, '•••••');

/** Текст сообщения для строк поиска и уведомлений: у кода входа (login_code) код скрыт. */
export const shownBody = (m: { body: string; service?: { type: string } | null }): string =>
  m.service?.type === 'login_code' ? hideCode(m.body) : m.body;

/** «печатает…» как в Telegram: в группе — с именами (имя, два имени, имя и ещё N); имён не знаем — числом. */
export function typingText(typers?: string[] | null): string {
  const n = typers?.length ?? 0, [a, b] = typers ?? [];
  if (n <= 1) return a ? `${a} печатает…` : 'печатает…';
  if (n === 2 && a && b) return `${a} и ${b} печатают…`;
  if (a) return `${a} и ещё ${n - 1} печатают…`;
  return `${n} ${n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14) ? 'человека' : 'человек'} печатают…`;
}
