import { replyArgs, type ReplyRef } from './replyRef';
import { captureSticker } from './ui/sendFlight';
// Стикеры в интерфейсе: вызовы движка (мои паки, паки, отправка) и открытие модалки пака.
// Движок отдаёт data.ts через bindStickers — здесь своя тонкая обёртка, чтобы стикеры не разрастались в data.ts.
import type { MyStickers, StickerRef, StickerSet, StickerSetInfo } from '@relay/protocol';
import { useEffect, useState } from 'preact/hooks';
import { setGlobal, useGlobal } from './global';

type Call = (a: Record<string, unknown> & { type: string }) => Promise<unknown>;
let call: Call = () => Promise.reject(new Error('engine is not ready'));

/** data.ts передаёт вызов движка при старте. */
export function bindStickers(fn: Call): void { call = fn; }

export const EMPTY_MINE: MyStickers = { sets: [], recent: [], faved: [] };

export const loadMyStickers = () => call({ type: 'myStickers' }) as Promise<MyStickers & { offline?: boolean }>;
export const loadStickerSet = (id: number | string, hash?: string) => call({ type: 'stickerSet', id, ...(hash ? { hash } : {}) }) as Promise<StickerSet | null>;
export const featuredSets = (offset = 0) => call({ type: 'featuredStickerSets', offset }) as Promise<StickerSetInfo[]>;
export const searchSets = (q: string) => call({ type: 'searchStickerSets', q }) as Promise<StickerSetInfo[]>;
export const stickersByEmoji = (emoji: string) => call({ type: 'stickersByEmoji', emoji }) as Promise<StickerRef[]>;
export const installSet = (setId: number, on: boolean, info?: StickerSetInfo) => call({ type: 'installStickerSet', setId, on, ...(info ? { info } : {}) });
export const faveSticker = (s: StickerRef, on: boolean) => call({ type: 'faveSticker', id: s.id, on, sticker: s });
export const clearRecentStickers = (id?: number) => call({ type: 'clearRecentStickers', ...(id != null ? { id } : {}) });
export const greetingSticker = () => call({ type: 'greetingSticker' }) as Promise<StickerRef | null>;
export const sendSticker = (chatId: number, sticker: StickerRef, replyToId?: ReplyRef, threadId?: number, when: { silent?: boolean; scheduleAt?: number; keepDraft?: boolean } = {}) => call({ type: 'sendSticker', ...when, chatId, sticker, ...replyArgs(replyToId), ...(threadId != null ? { threadId } : {}) });

/*
 * Стикер-приветствие пустого личного чата: случайный, но один на открытие чата (кадр стека) — перерисовки и
 * возврат в припаркованный кадр его не меняют, новое открытие берёт новый. Держим несколько последних кадров.
 */
const greetings = new Map<string, Promise<StickerRef | null>>();
const GREET_KEY = 'relay.greetings';   // последние стикеры-приветствия: без сети карточка не ждёт, а берёт один из них
function savedGreetings(): StickerRef[] { try { return JSON.parse(localStorage.getItem(GREET_KEY) ?? '[]') as StickerRef[]; } catch { return []; } }
/** Новый случайный с сервера (и в запас); без сети — один из запомненных, если они есть. */
async function askGreeting(): Promise<StickerRef | null> {
  const s = await greetingSticker().catch(() => null);
  const saved = savedGreetings();
  if (s) {
    try { localStorage.setItem(GREET_KEY, JSON.stringify([s, ...saved.filter((x) => x.id !== s.id)].slice(0, 8))); } catch { /* без хранилища — просто не запомним */ }
    return s;
  }
  return saved.length ? saved[Math.floor(Math.random() * saved.length)] : null;
}
const GREETING_WAIT = 1000;   // дольше стикер не ждём: карточка показывается без него, а опоздавший раскрывается в ней
/** undefined — ещё выбираем (карточку не показывать), null — без стикера. */
export function useGreetingSticker(frameKey: string, want: boolean): StickerRef | null | undefined {
  const [got, setGot] = useState<{ key: string; sticker: StickerRef | null } | null>(null);
  const known = got?.key === frameKey;
  useEffect(() => {
    if (!want || known) return;
    let p = greetings.get(frameKey);
    if (!p) {
      p = askGreeting();
      greetings.set(frameKey, p);
      if (greetings.size > 8) greetings.delete(greetings.keys().next().value!);
    }
    let live = true;
    const done = (sticker: StickerRef | null) => { if (live) { live = false; setGot({ key: frameKey, sticker }); } };
    const t = setTimeout(() => done(null), GREETING_WAIT);
    // null — движок ещё без сети: не сдаёмся раньше срока, ответ после подключения успеет (эффект ниже);
    // опоздал к показу — карточка уже без стикера: он всё равно встанет, плавно (GreetingCard)
    void p.then((s) => { if (!s) { greetings.delete(frameKey); return; } if (live) done(s); else setGot((g) => g?.key === frameKey && !g.sticker ? { key: frameKey, sticker: s } : g); });
    return () => { live = false; clearTimeout(t); };
  }, [frameKey, want, known]);
  // без сети движок сразу отвечает null (так бывает сразу после запуска, пока он подключается); сеть появилась —
  // спрашиваем ещё раз: успели до срока — карточка выходит сразу со стикером, нет — он встанет в неё позже
  const online = useGlobal((s) => s.status.online);
  const missing = !known || !got!.sticker;
  useEffect(() => {
    if (!want || !missing || !online) return;
    let live = true;
    let p = greetings.get(frameKey);
    if (!p) { p = askGreeting(); greetings.set(frameKey, p); }
    void p.then((s) => {
      if (!s) { greetings.delete(frameKey); return; }
      if (live) setGot((g) => g?.key === frameKey && g.sticker ? g : { key: frameKey, sticker: s });
    });
    return () => { live = false; };
  }, [frameKey, want, missing, online]);
  return known ? got!.sticker : undefined;
}

/** Мои стикеры, свежие: перечитываются, когда движок поднимает stickersRev (журнал, переподключение, свои действия). */
export function useMyStickers(): MyStickers {
  const rev = useGlobal((s) => (s.status as { stickersRev?: number }).stickersRev ?? 0);
  const [mine, setMine] = useState<MyStickers>(lastMine);
  useEffect(() => {
    let live = true;
    loadMyStickers().then((m) => { if (live) { lastMine = m; setMine(m); } }, () => {});
    return () => { live = false; };
  }, [rev]);
  return mine;
}
let lastMine: MyStickers = EMPTY_MINE;

/** Куда уходит стикер, выбранный в модалке или правой панели: открытый чат и его текущий ответ (ставит Chat). */
// schedule — страница отложенных: стикер не уходит сразу, спрашивается время
type When = { silent?: boolean; scheduleAt?: number; keepDraft?: boolean };
type Target = { chatId: number; threadId?: number; replyId: () => ReplyRef; sent: () => void; schedule?: (send: (w: When) => void) => void; later?: (done: (r: { at: number; silent: boolean }) => void) => void; saved?: boolean };   // threadId — комментарий в треде; later — окно «Отправить позже» (не в треде); saved — «Избранное»
let target: Target | null = null;
export function setStickerTarget(t: Target | null): () => void {
  target = t;
  return () => { if (target === t) target = null; };
}
export const hasStickerTarget = () => !!target;
/** Цель отправки: та же для GIF (gifs.ts). */
export const stickerTarget = () => target;
/** Отправить в открытый чат (с ответом, если он выбран). false — чата нет. */
export function sendStickerHere(s: StickerRef): boolean {
  if (!target) return false;
  if (target.schedule) {
    const t = target;
    t.schedule!((w) => void sendSticker(t.chatId, s, t.replyId(), t.threadId, w));
    t.sent();
    return true;
  }
  captureSticker(target.chatId);   // полёт картинки из панели в сообщение (sendFlight)
  void sendSticker(target.chatId, s, target.replyId(), target.threadId);
  target.sent();
  return true;
}

/** Модалка пака (клик по стикеру в ленте, панель, правая панель). Модуль грузится при первом открытии. */
export function openStickerSet(idOrShort: number | string): void {
  void import('./ui/stickers/StickerSetModal').then((m) => m.showStickerSet(idOrShort));
}

/** «Стикеры» (из поиска в панели эмодзи) — страница правой панели «Информация», вторая вложенность. */
export function openStickersPanel(): void { setGlobal({ infoOpen: true, infoGo: 'stickers' }); }
